/**
 * BEFORE & AFTER RESULTS
 *
 * Real cases are generated by `npm run results:prepare` into
 * `src/content/results.generated.json` (see scripts/prepare-results.ts).
 * Until then, the gallery shows clearly labelled ILLUSTRATIONS: scalp-map
 * diagrams, never presented as a patient's result.
 *
 * Rules for publishing a case:
 *  - written consent from the patient for this specific use,
 *  - unretouched photos: no AI upscaling, no filters, no editing of hair,
 *  - before and after taken with matching angle, distance and lighting.
 */
import generated from "./results.generated.json";

export type ResultCategory = "fue" | "dhi" | "hairline" | "crown";
export type ResultImage = { src: string; width: number; height: number };

export type ResultCase = {
  id: string;
  title: string;
  categories: ResultCategory[];
  technique: string;
  grafts?: string;
  timeAfter: string;
  note?: string;
  before: ResultImage;
  after: ResultImage;
  /** Optional progress photos between before and after, in order. */
  stages?: { label: string; image: ResultImage }[];
  placeholder: boolean;
};

export const RESULT_FILTERS: { value: "all" | ResultCategory; label: string }[] = [
  { value: "all", label: "All results" },
  { value: "fue", label: "FUE" },
  { value: "dhi", label: "DHI" },
  { value: "hairline", label: "Hairline" },
  { value: "crown", label: "Crown" },
];

/** Every frame of a case, before → progress → after, for the timeline view. */
export function caseFrames(c: ResultCase) {
  return [
    { label: "Before", image: c.before },
    ...(c.stages ?? []),
    { label: c.placeholder ? "12 months" : c.timeAfter, image: c.after },
  ];
}

const ill = (pattern: string, stage: string): ResultImage => ({ src: `/placeholders/${pattern}-${stage}.webp`, width: 1200, height: 1500 });

const PLACEHOLDERS: ResultCase[] = (
  [
    ["illustration-1", ["fue", "hairline", "crown"], "FUE", "both"],
    ["illustration-2", ["dhi", "hairline"], "DHI", "recession"],
    ["illustration-3", ["fue", "crown"], "FUE", "crown"],
    ["illustration-4", ["dhi", "hairline"], "DHI", "recession"],
    ["illustration-5", ["fue", "crown"], "FUE", "crown"],
    ["illustration-6", ["fue", "hairline", "crown"], "FUE", "both"],
  ] as const
).map(([id, categories, technique, pattern]) => ({
  id,
  title: "Illustration",
  categories: [...categories],
  technique,
  timeAfter: "Time since procedure",
  grafts: "Graft count",
  before: ill(pattern, "before"),
  after: ill(pattern, "12-months"),
  stages: [
    { label: "3 months", image: ill(pattern, "3-months") },
    { label: "6 months", image: ill(pattern, "6-months") },
  ],
  placeholder: true,
}));

type Generated = Omit<ResultCase, "placeholder">;
const real = (generated as { cases: Generated[] }).cases.map((c) => ({ ...c, placeholder: false }));

export const RESULTS: ResultCase[] = real.length > 0 ? real : PLACEHOLDERS;
export const HAS_REAL_RESULTS = real.length > 0;
export const FEATURED: ResultCase = RESULTS[0];

export const PLACEHOLDER_NOTE = "Illustration · authentic patient photographs to be supplied";
